\label{mainthm:Mumford-Tate conjecture for HK}
\label{mainthm:semisimplicity conjecture}
Let $X$ be a hyper-K\"ahler variety over a field $F$ finitely generated over ${\mathds Q}$.
Then $H^i_{\mathrm{\acute{e}t}}(X_{\overline F},{\mathds Q}_\ell)$ is a semisimple $G_F$-representation for every $i$ and every prime $\ell$, and the Mumford--Tate conjecture holds for $X$ in every degree.

\label{Corollary:introduction WMC for HK}
Let $K$ be a finite extension of ${\mathds Q}_p$, and let $X$ be a hyper-K\"ahler variety over $K$.
The weight--monodromy conjecture holds for $H^i_\mathrm{\acute{e}t}(X_{\overline K},{\mathds Q}_\ell)$ for every $i$ and every prime $\ell$, including $\ell=p$.

\label{Theorem:introduction rational compatibility for HK}
After replacing $F$ by a further finite extension, the family $\{\rho^{\operatorname{MT}}_{\ell,v}\}_\ell$ is rationally strongly compatible for every finite place $v$ of $F$.
More precisely, there exists a $\mathbf{G}$-valued Weil--Deligne representation $\rho_v$ of $F_v$ over $\overline{\mathds Q}$ whose $\mathbf{G}(\overline{\mathds Q})$-conjugacy class is invariant under $\mathop{\mathrm{Gal}}\nolimits(\overline{\mathds Q}/{\mathds Q})$ and whose base change to $\overline{{\mathds Q}}_\ell$ is equivalent to $\rho^{\operatorname{MT}}_{\ell,v}$ for every $\ell$, including $\ell=p$.

\label{Theorem:introduction integral compatibility for HK}
We keep the notation of \Cref{Theorem:introduction rational compatibility for HK} and fix a finite place $v\mid p$ of $F$.
There exist a positive integer $D$ divisible by $p$ and a reductive model $\mathcal{G}$ of $\mathbf{G}$ over ${\mathds Z}[1/D]$ such that $\rho_v$ extends to a $\mathcal{G}$-valued Weil--Deligne representation $\rho_v^{\mathrm{int}}$ of $F_v$ over $\overline{{\mathds Z}}[1/D]$ and, for every prime $\ell\nmid D$, its base change $(\rho_v^{\mathrm{int}})_{\overline{{\mathds Z}}_\ell}$ to $\overline{{\mathds Z}}_\ell$ is equivalent to the $\mathcal{G}$-valued Weil--Deligne representation $\rho^{\operatorname{MT},\mathrm{int}}_{\ell,v}$ of $F_v$ over $\overline{{\mathds Z}}_\ell$ associated with the Galois action on $H^\bullet_\mathrm{\acute{e}t}(X_{\overline{F}_v},{\mathds Z}_\ell)$.

\label{thm: MT conjecture}
For every prime $\ell$, we have
\begin{equation}\label{eq: MT conjecture}
\mathrm{G}_\ell(X)^\circ=\operatorname{MT}(X_{\mathds C})_{{\mathds Q}_\ell}
\end{equation}
under the \'etale--Betti comparison.
Moreover, for each $0\leq i\leq 2\dim X$, $H^i_{\mathrm{\acute{e}t}}(X_{\overline F},{\mathds Q}_\ell)$ is a semisimple $G_F$-representation and the Mumford--Tate conjecture $\textup{(MTC)}_i$ holds for $X$.

\label{rem:functorial in groups}
   The constructions of $\mathbf{G}$-valued Weil--Deligne representations $\phi \mapsto \rho(\phi)$ in 
   \Cref{Example: WD rep ell adic case,Example: WD rep p adic case} are both functorial in $\mathbf{G}$, up to equivalence.

\label{Conjecture:WMC}
    Let $X$ be a smooth proper scheme over $K$.
    Then, for every prime $\ell$ and every integer $i$, the Weil--Deligne representation associated with $H^i_{\mathrm{\acute{e}t}}(X_{\overline K},{\mathds Q}_\ell)$ is pure of weight $i$.

\label{lem:WMC in degree 2}
    Let $X$ be a smooth proper scheme over $K$.
    The weight--monodromy conjecture \textup{(\Cref{Conjecture:WMC})} holds for $i\leq 2$.

\label{prop:global Frobenius semisimplicity}
For every prime $\ell$ and every $i$, the Weil--Deligne representation $\rho_{\ell, i}$ of $K$ over $\overline{{\mathds Q}}_\ell$ associated with $H^i_\mathrm{\acute{e}t}(X_{\overline{K}}, {\mathds Q}_\ell)$ is Frobenius semisimple.
The $\mathbf{G}$-valued Weil--Deligne representation $\rho^{\operatorname{MT}}_\ell$ is also Frobenius semisimple.

\label{lem:weighted tensor generation}
    Let $V_i=H^i_B(X_{\mathds C},{\mathds Q})$ for each integer $0\leq i\leq 2\dim X$.
    \begin{enumerate}
        \item The action of $\mathbf{G}$ on $V^{\otimes 2}_i\coloneqq V_i\otimes V_i$ factors through $\mathbf{G}_2$.
        \item As a $\mathbf{G}_2$-representation, $V^{\otimes 2}_i$ is a direct summand of a finite direct sum of representations $ V_2^{\otimes m}\otimes  V_2^{\vee,\otimes n} $ for some $m,n\geq 0$ with $m-n=i$.
    \end{enumerate}

\label{lem:tensor-square defector of purity}
    Let $\rho=(r,N)$ be a Weil--Deligne representation of $K$ over $\overline{{\mathds Q}}_\ell$.
    If $\rho\otimes\rho$ is pure of weight $2i$ for some integer $i$, then $\rho$ is pure of weight $i$.

\label{Theorem:purity of Weil-Deligne representations}
Let $X$ be a hyper-K\"ahler variety over $K$.
For every prime $\ell$ and every integer $0\leq i\leq 2\dim X$, the Weil--Deligne representation $\rho_{\ell, i}$ is pure of weight $i$.

\label{Definition:rational strong compatibility}
The family $\{\rho^{\operatorname{MT}}_{\ell,v}\}_\ell$ is \emph{rationally strongly compatible} if there exists a $\mathbf{G}$-valued Weil--Deligne representation $\rho_v$ of $F_v$ over $\overline{{\mathds Q}}$ satisfying the following conditions:
\begin{enumerate}
    \item ${}^{\sigma}\rho_v \sim_{\mathbf{G}(\overline{{\mathds Q}})}\rho_v$ for every $\sigma \in G_{\mathds Q}$, where ${}^{\sigma}\rho_v$ denotes the base change of $\rho_v$ along $\sigma \colon \overline{{\mathds Q}}  
  \mathrel{\overset{\raisebox{-0.35ex}{$\scriptstyle\sim$}}{\rightarrow}} 
 \overline{{\mathds Q}}$.
    \item $\rho_v \otimes_{\overline{{\mathds Q}}} \overline{{\mathds Q}}_\ell \sim_{\mathbf{G}(\overline{{\mathds Q}}_\ell)} \rho^{\operatorname{MT}}_{\ell,v}$ for every $\ell$, including $\ell=p$.
\end{enumerate}

\label{Theorem:strongly compatiblity for abelian variety}
In the above setting, suppose that $X$ is an abelian variety with semistable reduction at $v$.
Then $\{\rho^{\operatorname{MT}}_{\ell,v}\}_\ell$ is rationally strongly compatible.

\label{Remark:torsion WMC}
The torsion analogue of the weight--monodromy conjecture formulated in \cite[Conjecture~3.5]{Ito21} also holds for hyper-K\"ahler varieties over $K$ in every degree.
Indeed, this follows from \Cref{Theorem:purity of Weil-Deligne representations} and \Cref{Proposition: torsion freeness of cohomological monodromy} together with \cite[Proposition~3.10(iii)]{Ito21}.

\label{Proposition: integral purity of MT representations}
There exists a positive integer $D$ divisible by $D_0$, such that, for every prime $\ell\nmid D$, both
\[
(\rho_v^{\mathrm{int}})_{\overline{{\mathds Z}}_\ell}
\quad\text{and}\quad
\rho^{\operatorname{MT},\mathrm{int}}_{\ell,v}
\]
are pure with respect to $\mu$ in the sense of \Cref{Definition:integral G-valued purity}.

\label{Theorem:integral compatibility for HK}
There exists a positive integer $D$ divisible by $D_0$, such that, for every prime $\ell\nmid D$, we have
\[
(\rho_v^{\mathrm{int}})_{\overline{{\mathds Z}}_\ell}
\sim_{\mathcal{G}(\overline{{\mathds Z}}_\ell)}
\rho^{\operatorname{MT},\mathrm{int}}_{\ell,v}.
\]
